import{_ as n,a0 as d,w as p,s as g,I as t,x as s,a1 as a,A as l,ao as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何使用 Tig 浏览 Git 日志 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 Tig 浏览 Git 日志 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 Tig 浏览 Git 日志 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 Tig 浏览 Git 日志 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190627 How to use Tig to browse Git logs","title":"如何使用 Tig 浏览 Git 日志","tag":"201907","desc":""},"relativePath":"201907/20190627 How to use Tig to browse Git logs.md","filePath":"[post].md"}'),r={name:"201907/20190627 How to use Tig to browse Git logs.md"};function h(u,i,b,k,c,f){const e=d("Link");return p(),g("div",null,[i[30]||(i[30]=t("h1",{id:"如何使用-tig-浏览-git-日志",tabindex:"-1"},[s("如何使用 Tig 浏览 Git 日志 "),t("a",{class:"header-anchor",href:"#如何使用-tig-浏览-git-日志","aria-label":"Permalink to “如何使用 Tig 浏览 Git 日志”"},"​")],-1)),i[31]||(i[31]=t("blockquote",null,[t("p",null,"Tig 可不仅仅是 Git 的文本界面。以下是它如何增强你的日常工作流程。")],-1)),i[32]||(i[32]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/201907/07/111847v1zx3qk5qqhklyjp.png",alt:""})],-1)),t("p",null,[i[1]||(i[1]=s("如果你使用 Git 作为你的版本控制系统，你可能已经让自己接受了 Git 是一个复杂的野兽的事实。它是一个很棒的工具，但浏览 Git 仓库可能很麻烦。因此像 ",-1)),a(e,{href:"https://jonas.github.io/tig/"},{default:l(()=>[...i[0]||(i[0]=[s("Tig",-1)])]),_:1}),i[2]||(i[2]=s(" 这样的工具出现了。",-1))]),t("p",null,[i[4]||(i[4]=s("来自 ",-1)),a(e,{href:"http://manpages.ubuntu.com/manpages/bionic/man1/tig.1.html"},{default:l(()=>[...i[3]||(i[3]=[s("Tig 手册页",-1)])]),_:1}),i[5]||(i[5]=s("：",-1))]),i[33]||(i[33]=o('<blockquote><p>Tig 是 <code>git</code>(1) 的基于 ncurses 的文本界面。它主要用作 Git 仓库浏览器，但也有助于在块级别暂存提交更改，并作为各种 Git 命令的输出分页器。</p></blockquote><p>这基本上意味着 Tig 提供了一个可以在终端中运行的基于文本的用户界面。Tig 可以让你轻松浏览你的 Git 日志，但它可以做的远不止让你从最后的提交跳到前一个提交。</p><p><img src="https://opensource.com/sites/default/files/uploads/tig.jpg" alt="Tig screenshot" title="Tig screenshot"></p><p>这篇快速入门的 Tig 中的许多例子都是直接从其出色的手册页中拿出来的。我强烈建议你阅读它以了解更多信息。</p><h3 id="安装-tig" tabindex="-1">安装 Tig <a class="header-anchor" href="#安装-tig" aria-label="Permalink to “安装 Tig”">​</a></h3><ul><li>Fedora 和 RHEL： <code>sudo dnf install tig</code></li><li>Ubuntu 和 Debian： <code>sudo apt install tig</code></li><li>MacOS： <code>：brew install tig</code></li></ul>',6)),t("p",null,[i[7]||(i[7]=s("有关更多方式，请参阅官方",-1)),a(e,{href:"https://jonas.github.io/tig/INSTALL.html"},{default:l(()=>[...i[6]||(i[6]=[s("安装说明",-1)])]),_:1}),i[8]||(i[8]=s("。",-1))]),i[34]||(i[34]=o('<h3 id="浏览当前分支中的提交" tabindex="-1">浏览当前分支中的提交 <a class="header-anchor" href="#浏览当前分支中的提交" aria-label="Permalink to “浏览当前分支中的提交”">​</a></h3><p>如果要浏览分支中的最新提交，请输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tig</span></span></code></pre></div><p>就是这样。这个三字符命令将启动一个浏览器，你可以在其中浏览当前分支中的提交。你可以将其视为 <code>git log</code> 的封装器。</p><p>要浏览这些输出，可以使用向上和向下箭头键从一个提交移动到另一个提交。按回车键将会垂直分割窗口，右侧包含所选提交的内容。你可以继续在左侧的提交历史记录中上下浏览，你的更改将显示在右侧。使用 <code>k</code> 和 <code>j</code> 可以逐行上下浏览，<code>-</code> 和空格键可以在右侧上下翻页。使用 <code>q</code> 退出右侧窗格。</p><p>搜索 <code>tig</code> 输出也很简单。使用 <code>/</code> （向前）或 <code>?</code> （向后）在左右窗格中搜索。</p><p><img src="https://opensource.com/sites/default/files/uploads/tig-search.png" alt="Searching Tig" title="Searching Tig"></p><p>这些就足以让你浏览你的提交信息了。这里有很多的键绑定，但单击 <code>h</code> 将显示“帮助”菜单，你可以在其中发现其导航和命令选项。你还可以使用 <code>/</code> 和 <code>?</code> 来搜索“帮助”菜单。使用 <code>q</code> 退出帮助。</p><p><img src="https://opensource.com/sites/default/files/uploads/tig-help.png" alt="Tig Help" title="Tig Help"></p><h3 id="浏览单个文件的修改" tabindex="-1">浏览单个文件的修改 <a class="header-anchor" href="#浏览单个文件的修改" aria-label="Permalink to “浏览单个文件的修改”">​</a></h3><p>由于 Tig 是 <code>git log</code> 的封装器，它可以方便地接受可以传递给 <code>git log</code> 的相同参数。例如，要浏览单个文件的提交历史记录，请输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tig README.md</span></span></code></pre></div><p>将其与被封装的 Git 命令的输出进行比较，以便更清楚地了解 Tig 如何增强输出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git log README.md</span></span></code></pre></div><p>要在原始 Git 输出中包含补丁，你可以添加 <code>-p</code> 选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git log -p README.md</span></span></code></pre></div><p>如果要将提交范围缩小到特定日期范围，请尝试以下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tig --after=&quot;2017-01-01&quot; --before=&quot;2018-05-16&quot; -- README.md</span></span></code></pre></div><p>再一次，你可以将其与原始的 Git 版本进行比较：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git log --after=&quot;2017-01-01&quot; --before=&quot;2018-05-16&quot; -- README.md</span></span></code></pre></div><h3 id="浏览谁更改了文件" tabindex="-1">浏览谁更改了文件 <a class="header-anchor" href="#浏览谁更改了文件" aria-label="Permalink to “浏览谁更改了文件”">​</a></h3><p>有时你想知道谁对文件进行了更改以及原因。命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tig blame README.md</span></span></code></pre></div><p>器本质上是 <code>git blame</code> 的封装。正如你所期望的那样，它允许你查看谁是编辑指定行的最后一人，它还允许你查看到引入该行的提交。这有点像 vim 的 <code>vim-fugitive</code> 插件提供的 <code>:Gblame</code> 命令。</p><h3 id="浏览你的暂存区" tabindex="-1">浏览你的暂存区 <a class="header-anchor" href="#浏览你的暂存区" aria-label="Permalink to “浏览你的暂存区”">​</a></h3><p>如果你像我一样，你可能会在你的暂存区做了许多修改。你很容易忘记它们。你可以通过以下方式查看暂存处中的最新项目：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git stash show -p stash@{0}</span></span></code></pre></div><p>你可以通过以下方式找到第二个最新项目：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git stash show -p stash@{1}</span></span></code></pre></div><p>以此类推。如果你在需要它们时调用这些命令，那么你会有比我更清晰的记忆。</p><p>与上面的 Git 命令一样，Tig 可以通过简单的调用轻松增强你的 Git 输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tig stash</span></span></code></pre></div><p>尝试在有暂存的仓库中执行此命令。你将能够浏览<em>并搜索</em>你的暂存项，快速浏览你的那些修改。</p><h3 id="浏览你的引用" tabindex="-1">浏览你的引用 <a class="header-anchor" href="#浏览你的引用" aria-label="Permalink to “浏览你的引用”">​</a></h3><p>Git ref 是指你提交的东西的哈希值。这包括文件和分支。使用 <code>tig refs</code> 命令可以浏览所有的 ref 并深入查看特定提交。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tig refs</span></span></code></pre></div><p>完成后，使用 <code>q</code> 回到前面的菜单。</p><h3 id="浏览-git-状态" tabindex="-1">浏览 git 状态 <a class="header-anchor" href="#浏览-git-状态" aria-label="Permalink to “浏览 git 状态”">​</a></h3><p>如果要查看哪些文件已被暂存，哪些文件未被跟踪，请使用 <code>tig status</code>，它是 <code>git status</code> 的封装。</p><p><img src="https://opensource.com/sites/default/files/uploads/tig-status.png" alt="Tig status" title="Tig status"></p><h3 id="浏览-git-grep" tabindex="-1">浏览 git grep <a class="header-anchor" href="#浏览-git-grep" aria-label="Permalink to “浏览 git grep”">​</a></h3><p>你可以使用 <code>grep</code> 命令在文本文件中搜索表达式。命令 <code>tig grep</code> 允许你浏览 <code>git grep</code> 的输出。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tig grep -i foo lib/Bar</span></span></code></pre></div><p>它会让你浏览 <code>lib/Bar</code> 目录中以大小写敏感的方式搜索 <code>foo</code> 的输出。</p><h3 id="通过标准输入管道输出给-tig" tabindex="-1">通过标准输入管道输出给 Tig <a class="header-anchor" href="#通过标准输入管道输出给-tig" aria-label="Permalink to “通过标准输入管道输出给 Tig”">​</a></h3><p>如果要将提交 ID 列表传递给 Tig，那么必须使用 <code>--stdin</code> 标志，以便 <code>tig show</code> 从标准输入读取。否则，<code>tig show</code> 会在没有输入的情况下启动（出现空白屏幕）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git rev-list --author=olaf HEAD | tig show --stdin</span></span></code></pre></div><h3 id="添加自定义绑定" tabindex="-1">添加自定义绑定 <a class="header-anchor" href="#添加自定义绑定" aria-label="Permalink to “添加自定义绑定”">​</a></h3>',48)),t("p",null,[i[10]||(i[10]=s("你可以使用 ",-1)),a(e,{href:"https://en.wikipedia.org/wiki/Run_commands"},{default:l(()=>[...i[9]||(i[9]=[s("rc",-1)])]),_:1}),i[11]||(i[11]=s(" 文件自定义 Tig。以下是如何根据自己的喜好添加一些有用的自定义键绑定的示例。",-1))]),i[35]||(i[35]=o(`<p>在主目录中创建一个名为 <code>.tigrc</code> 的文件。在你喜欢的编辑器中打开 <code>~/.tigrc</code> 并添加：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 应用选定的暂存内容</span></span>
<span class="line"><span>bind stash a !?git stash apply %(stash)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 丢弃选定的暂存内容</span></span>
<span class="line"><span>bind stash x !?git stash drop %(stash)</span></span></code></pre></div><p>如上所述，运行 <code>tig stash</code> 以浏览你的暂存。但是，通过这些绑定，你可以按 <code>a</code> 将暂存中的项目应用到仓库，并按 <code>x</code> 从暂存中删除项目。请记住，你要在浏览暂存<em>列表</em>时，才能执行这些命令。如果你正在浏览暂存<em>项</em>，请输入 <code>q</code> 退出该视图，然后按 <code>a</code> 或 <code>x</code> 以获得所需效果。</p>`,3)),t("p",null,[i[13]||(i[13]=s("有关更多信息，你可以阅读有关 ",-1)),a(e,{href:"https://github.com/jonas/tig/wiki/Bindings"},{default:l(()=>[...i[12]||(i[12]=[s("Tig 键绑定",-1)])]),_:1}),i[14]||(i[14]=s("。",-1))]),i[36]||(i[36]=t("h3",{id:"总结",tabindex:"-1"},[s("总结 "),t("a",{class:"header-anchor",href:"#总结","aria-label":"Permalink to “总结”"},"​")],-1)),i[37]||(i[37]=t("p",null,"我希望这有助于演示 Tig 如何增强你的日常工作流程。Tig 可以做更强大的事情（比如暂存代码行），但这超出了这篇介绍性文章的范围。这里有足够的让你置身于危险的信息，但还有更多值得探索的地方。",-1)),i[38]||(i[38]=t("hr",null,null,-1)),t("p",null,[i[16]||(i[16]=s("via: ",-1)),a(e,{href:"https://opensource.com/article/19/6/what-tig"},{default:l(()=>[...i[15]||(i[15]=[s("https://opensource.com/article/19/6/what-tig",-1)])]),_:1})]),t("p",null,[i[21]||(i[21]=s("作者：",-1)),a(e,{href:"https://opensource.com/users/oalders/users/mbbroberg/users/marcobravo"},{default:l(()=>[...i[17]||(i[17]=[s("Olaf Alders",-1)])]),_:1}),i[22]||(i[22]=s(" 选题：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:l(()=>[...i[18]||(i[18]=[s("lujun9972",-1)])]),_:1}),i[23]||(i[23]=s(" 译者：",-1)),a(e,{href:"https://github.com/geekpi"},{default:l(()=>[...i[19]||(i[19]=[s("geekpi",-1)])]),_:1}),i[24]||(i[24]=s(" 校对：",-1)),a(e,{href:"https://github.com/wxy"},{default:l(()=>[...i[20]||(i[20]=[s("wxy",-1)])]),_:1})]),t("p",null,[i[27]||(i[27]=s("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...i[25]||(i[25]=[s("LCTT",-1)])]),_:1}),i[28]||(i[28]=s(" 原创编译，",-1)),a(e,{href:"https://linux.cn/"},{default:l(()=>[...i[26]||(i[26]=[s("Linux中国",-1)])]),_:1}),i[29]||(i[29]=s(" 荣誉推出",-1))])])}const y=n(r,[["render",h]]);export{C as __pageData,y as default};
